export type TranslationKey = keyof typeof messages;
export const resources = Object.fromEntries(localeCodes.map((code, index) => [
  code,
  { translation: Object.fromEntries(Object.entries(messages).map(([key, values]) => [key, values[index]])) },
])) as Record<Locale, { translation: Record<TranslationKey, string> }>;
